Definition pfc_kn (c : Z) : list kentry :=
  [KWr (SA (EVar 2) (- PFC_FRAME)) (ELit PFC_FRAME); KRange (EVar 2) (2 ^ 33 + PFC_FRAME) (2 ^ 47); KAlign (EVar 2) 16;
   KRange (EVar 11) (2 ^ 32) (2 ^ 47 - 68);
   KWord (SA (EVar 11) 0) (N.to_nat 1) (ELit 37); KWord (SA (EVar 11) 1) (N.to_nat 1) (ELit 108);
   KWord (SA (EVar 11) 2) (N.to_nat 1) (ELit c); KWord (SA (EVar 11) 3) (N.to_nat 1) (ELit 0);
   KDisj (SA (EVar 11) 0) (ELit 4) (SA (EVar 2) (- PFC_FRAME)) (ELit PFC_FRAME);
   KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit ASHADOW_BASE);
   KZero (SA SHX0 0) (ELit 8); KZero (SA SHX3 0) (ELit 8);
   KDisj (SA SHX0 0) (ELit 8) (SA (EVar 2) (- PFC_FRAME)) (ELit PFC_FRAME); KDisj (SA SHX3 0) (ELit 8) (SA (EVar 2) (- PFC_FRAME)) (ELit PFC_FRAME);
   KImg 0x10000 0x17e000; KImg 0x17e000 0x186000].

Section Pfc.
  Context {HCEIL : HeapCeil}.
  Context {fx : FPState}.

  Lemma printf_common_l : forall R M (sp ret fmt conv lo shi : Z),
    getr R 1%bv = Z_to_bv 64 ret -> ret_ok (Z_to_bv 64 ret) -> 0 <= ret < 2 ^ 64 ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 11%bv = Z_to_bv 64 fmt ->
    2 ^ 33 <= sp - PFC_FRAME -> sp < 2 ^ 47 -> sp mod 16 = 0 -> mdef M (sp - PFC_FRAME) PFC_FRAME ->
    2 ^ 32 <= fmt -> (fmt + 4 <= sp - PFC_FRAME \/ sp <= fmt) ->
    fld SEGS M fmt 1 37 -> fld SEGS M (fmt + 1) 1 108 -> fld SEGS M (fmt + 2) 1 conv -> fld SEGS M (fmt + 3) 1 0 ->
    (conv = 117 \/ conv = 100 \/ conv = 120) ->
    mem_inv asegs M -> relro_clear M -> ACONST M ->
    stack0 M lo shi -> lo + 64 <= fmt -> fmt + 68 <= shi -> lo <= sp - PFC_FRAME ->
    exists R' M',
      msteps SEGS (@mkst fx R (Z_to_bv 64 APRINTF_COMMON) M (seg_rom SEGS)) (@mkst fx R' (Z_to_bv 64 ret) M' (seg_rom SEGS))
      /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
